import {renderStoryPaths,renderMove,renderLifeAlbum} from './stories-ui.js';
import {ROOMS,GIFTS,HOBBIES,LEVELS,BUCKETS,FIRST_WEEK,lifestyle,sceneOptions,bucketDone,quoteLife} from './lifestyle.js';
export function renderWorld(s,{escape:e,won,date}){const l=lifestyle(s),step=FIRST_WEEK[l.week],scene=l.scenes[0],disabled=s.ended?'disabled':'';
 const card=(kind,item)=>{const q=quoteLife(s,kind,item.id);return `<article class="world-option"><span class="world-option-mark">${kind==='room'?'⌂':kind==='gift'?'♡':'◇'}</span><h4>${e(item.name)}</h4><p>${e(item.detail)}</p><b>${won(q.cost)}</b><button class="btn secondary small" data-life-review="${kind}:${item.id}" ${q.disabled?'disabled':''}>${q.disabled?e(q.reason):'자세히 보고 선택 →'}</button></article>`;};
 const era=Number(s.month.slice(0,4))<2010?'그 시절의 취향을 담아':Number(s.month.slice(0,4))<2020?'여유를 누리는 방법':'나에게 맞는 일상';
 return `<div class="world-intro"><div><span class="eyebrow">MY SPACE / MY STORY</span><h2>돈으로 바꾼 건,<br>결국 나의 하루.</h2><p>사고 싶었던 것에서, 살아보고 싶었던 생활로.<br>내 취향의 공간과 소중한 기억을 하나씩 채워요.</p></div><div class="world-stamp"><strong>${l.moments.length}</strong><span>내가 만든 기억</span><small>${l.bucket.filter(id=>bucketDone(s,id)).length} / ${l.bucket.length} 꿈 실현</small></div></div>
 <div class="world-anchors"><a href="#world-paths">내 선택의 다음 장</a><a href="#world-story">당첨 첫 주</a><a href="#world-house">나의 집</a><a href="#world-family">함께 나누기</a><a href="#world-bucket">버킷리스트</a><a href="#world-move">지역 이사</a><a href="#world-album">삶의 앨범</a><a href="#world-moments">추억 앨범</a></div>
 ${renderStoryPaths(s,{escape:e,won,date})}<section id="world-story" class="world-story-grid">${step?`<article class="card week-card"><div class="event-top"><span class="mini-label">당첨 첫 주 · ${l.week+1} / ${FIRST_WEEK.length}</span><span class="eyebrow">THE FIRST WEEK</span></div><h3>${e(step.title)}</h3><p>${e(step.text)}</p><div class="options">${step.options.map(o=>`<button class="choice" data-life-do="week:${o.id}" ${disabled}><span><strong>${e(o.name)}</strong><small>비용 없음 · 선택을 추억으로 남겨요</small></span><span>↗</span></button>`).join('')}</div><p class="note">첫 주를 돌아보는 짧은 이야기예요. 실제 날짜를 하루씩 진행하거나 당첨금을 다시 지급하지 않습니다.</p></article>`:`<article class="card week-card"><span class="mini-label">THE FIRST WEEK · COMPLETE</span><h3>처음의 설렘이,<br>나만의 일상으로.</h3><p>당첨 직후의 세 장면을 기록했어요.<br>이제 내가 원하는 하루를 구체적으로 만들어 보세요.</p><button class="btn secondary" data-shop="home">살고 싶은 집 둘러보기 ↗</button></article>`}
 ${scene?`<article class="card scene-card"><span class="mini-label">구매 다음의 이야기 · ${l.scenes.length}개 대기</span><h3>${e(scene.name)}<br>나의 첫 순간.</h3><p>${e(scene.text)}</p><div class="options">${sceneOptions(scene).map(o=>`<button class="choice" data-life-do="scene:${o.id}" ${disabled}><span><strong>${e(o.name)}</strong><small>추가 비용 없음 · 만족 +2 · 추억에 기록</small></span><span>↗</span></button>`).join('')}</div><p class="note">동행은 이 장면에서의 설정이에요. 가족의 구성이나 관계를 미리 정하지 않습니다.</p></article>`:`<article class="card scene-card empty-scene"><span class="mini-label">AFTER THE PURCHASE</span><h3>열쇠를 받은 날.<br>첫 드라이브.<br>좋아하는 영화 한 편.</h3><p>집·차·물건·여행을 선택하면 구매 이후의 장면이 여기에 이어져요.</p><button class="text-button" data-shop="car">다음 꿈 만나러 가기 ↗</button></article>`}</section>
 <section id="world-house" class="world-section"><div class="section-heading"><div><span class="eyebrow">01 / A PLACE OF MY OWN</span><h3>평수보다, 내가 좋아하는 공간.</h3></div><span class="mini-label">${s.home?'내 집 꾸미기':'내 집을 고른 뒤 열려요'}</span></div><div class="house-layout"><div class="house-map"><span class="house-map-label">${e(s.homeDetails?.name||(s.home?'나의 집':'아직 그려 보는 집'))}</span><div class="house-floor"><div class="room-tile living-room"><span>함께 쉬는 거실</span><small>나의 일상</small></div>${ROOMS.map(r=>`<div class="room-tile ${l.rooms.includes(r.id)?'furnished':''}"><b>${l.rooms.includes(r.id)?'✓':'+'}</b><span>${e(r.name)}</span><small>${l.rooms.includes(r.id)?'내 취향으로 완성':'아직 빈 공간'}</small></div>`).join('')}</div><p class="note">방 배치는 개념도예요. 실제 주택 평면·면적이나 방 개수를 재현하지 않습니다.</p></div><div><p>꾸민 공간은 매일의 배경이 됩니다.<br>꾸미기 비용은 소비로 반영하며 집 평가액이나 월 유지비를 올리지 않아요.</p><div class="world-options rooms-options">${ROOMS.map(r=>card('room',r)).join('')}</div>${!s.home?'<button class="btn spacer" data-shop="home">내 집부터 고르기 →</button>':''}</div></div></section>
 <section id="world-family" class="world-section"><div class="section-heading"><div><span class="eyebrow">02 / PEOPLE I CARE ABOUT</span><h3>얼마를 주느냐보다, 어떻게 나눌까.</h3></div><span class="mini-label">월 1회</span></div><p>가족으로 생각하는 소중한 사람을 떠올려 보세요.<br>지원은 내 현금에서 나가며, 상대의 행복이나 관계 개선을 자동으로 보장하지 않습니다.</p><div class="world-options">${GIFTS.map(g=>card('gift',g)).join('')}</div></section>
 <section id="world-bucket" class="world-section bucket-section"><div class="bucket-panel"><span class="eyebrow">03 / MY BUCKET LIST</span><h3>남들의 꿈 말고,<br>나의 하고 싶은 일.</h3><p>원하는 목표를 눌러 담아 보세요.<br>실제로 행동하면 완료 표시가 남아요. 보상금이나 점수 경쟁은 없습니다.</p><div class="bucket-list">${BUCKETS.map(b=>`<button class="bucket-item ${l.bucket.includes(b.id)?'selected':''}" data-life-do="bucket:${b.id}" aria-pressed="${l.bucket.includes(b.id)}" ${disabled}><span>${l.bucket.includes(b.id)?'✓':'+'}</span><b>${e(b.name)}</b><small>${bucketDone(s,b.id)?'이룬 꿈':l.bucket.includes(b.id)?'나의 목록에 담음':'목록에 담기'}</small></button>`).join('')}</div><div class="hobby-options"><h4>무엇부터 배워볼까요?</h4>${HOBBIES.map(h=>{const q=quoteLife(s,'hobby',h.id);return `<button class="level-choice" data-life-review="hobby:${h.id}" ${q.disabled?'disabled':''}><b>${e(h.name)}</b><small>${won(q.cost)} · ${q.disabled?e(q.reason):'첫 체험 자세히 보기 →'}</small></button>`;}).join('')}</div></div><div class="card lifestyle-panel"><span class="eyebrow">EVERYDAY, MY WAY</span><h3>나의 생활 템포</h3><p>반복되는 일상의 소비를 정해요.<br>기본 생활비만 바뀌며 집·차 유지비는 별도입니다. 선택 자체의 비용과 만족 보너스는 없어요.</p>${LEVELS.map(v=>{const q=quoteLife(s,'level',v.id);return `<button class="level-choice ${l.level===v.id?'active':''}" data-life-review="level:${v.id}" ${q.disabled?'disabled':''}><b>${e(v.name)} ${l.level===v.id?'✓':''}</b><small>${e(v.detail)} · 월 변화 ${won(q.monthlyChange)}</small></button>`;}).join('')}<div class="era-note"><span class="mini-label">${date(s.month)} / ${era}</span><p>시대에 따라 게임 물가를 반영한 가격이 달라져요. 제품은 시대 공통의 가상 유형이며 실제 브랜드·출시 연도를 재현하지 않습니다.</p></div></div></section>
 ${renderMove(s,{escape:e,won,date})}${renderLifeAlbum(s,{escape:e,won,date})}<section id="world-moments" class="world-section"><div class="section-heading"><div><span class="eyebrow">04 / MOMENTS THAT STAY</span><h3>통장에 남지 않아도, 기억에는 남는 것.</h3></div><span class="mini-label">${l.moments.length}개의 장면</span></div><div class="moments-grid">${l.moments.length?l.moments.slice(-12).reverse().map((m,i)=>`<article class="moment-card"><span class="moment-number">${String(l.moments.length-i).padStart(2,'0')}</span><time>${date(m.month)}</time><h4>${e(m.title)}</h4><p>${e(m.text)}</p></article>`).join(''):'<p class="empty-state">첫 주의 이야기를 선택하면 첫 기억이 남아요.</p>'}</div>${l.moments.length>12?'<p class="note">최근 12개 장면입니다. 모든 기억은 ‘선택의 기록’과 내려받은 기록 파일에 남아요.</p>':''}</section><p class="game-assumption">공간 꾸미기·가족 지원·생활비·선택 효과는 모두 게임 가정입니다. 방 꾸미기에는 중고 가치나 투자 수익을 부여하지 않습니다.</p>`;
}
